    async def update(
        self,
        id: str,
        *,
        revision_number: str,
        account_id: str | NotGiven = NOT_GIVEN,
        inventory_site_id: str | NotGiven = NOT_GIVEN,
        transaction_date: _dt.date | NotGiven = NOT_GIVEN,
        ref_number: str | NotGiven | None = NOT_GIVEN,
        customer_id: str | NotGiven = NOT_GIVEN,
        class_id: str | NotGiven = NOT_GIVEN,
        memo: str | NotGiven | None = NOT_GIVEN,
        lines: Sequence[InventoryAdjustmentLineUpdateInput] | NotGiven = NOT_GIVEN,
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> InventoryAdjustment:
        """Update an inventory adjustment.

        Changes the fields you send on an existing inventory adjustment and leaves omitted fields unchanged. Requires the current `revisionNumber`. A stale `revisionNumber` returns `409 QBD_REVISION_NUMBER_STALE`: retrieve the inventory adjustment, reapply your change and send the new revision. Sending a line array replaces all existing lines of that kind. See [Updates and line items](https://www.desktopaccountingapi.com/docs/quickbooks/updates-and-line-items/).

        Operation ``qbd.inventoryAdjustments.update``: ``POST /v1/quickbooks-desktop/inventory-adjustments/{id}``.

        Args:
            id: QuickBooks ID of the inventory adjustment.
            revision_number: Current revision of this inventory adjustment. Send it unchanged when updating; a stale value is rejected.
            account_id: ID of the account for this inventory adjustment.
            inventory_site_id: ID of the inventory site for this inventory adjustment.
            transaction_date: Date of this inventory adjustment (YYYY-MM-DD).
            ref_number: Reference number of this inventory adjustment, such as an invoice or check number. Case-sensitive. Pass ``None`` to clear it.
            customer_id: ID of the customer for this inventory adjustment.
            class_id: ID of the class for this inventory adjustment.
            memo: Internal memo for this inventory adjustment; shown in reports, not on printed forms. Pass ``None`` to clear it.
            lines: Line items of this inventory adjustment. When present, replaces this array: keep an existing entry by sending its id (an id alone leaves it unchanged), add one with id "-1"; existing entries you leave out are deleted. Omit the array to keep the lines unchanged. An update cannot remove every line.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The InventoryAdjustment object.
        """
        return await self._client._request(
            _QBD_INVENTORY_ADJUSTMENTS_UPDATE,
            "POST",
            "/v1/quickbooks-desktop/inventory-adjustments/" + _pp("id", id),
            cast_to=InventoryAdjustment.from_wire,
            body={
                "revisionNumber": revision_number,
                "accountId": account_id,
                "inventorySiteId": inventory_site_id,
                "transactionDate": transaction_date,
                "refNumber": ref_number,
                "customerId": customer_id,
                "classId": class_id,
                "memo": memo,
                "lines": lines,
            },
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )

